```c
Status ListInvert_Sq(Sqlist list)
{        int i=0;
    if(list.length) //判断顺序表不为空
    {
        while ((i!=list.length-1-i)&&(list.length-1-i!=1))
        {
            ElemType temp;
            temp = list.elem[i];
            list.elem[i] = list.elem[list.length-i-1];
            list.elem[list.length-i-1] = temp;
            i++;
        }
    }
    else //顺序表为空
    {
        cout<<"Empty list!"<<endl;
        return FALSE;
    }
    return OK;
}
