```c
Status MergeLinkList(LinkList &A, LinkList &B)
{// 假设A、B都含有头结点，先将A、B合并，再将其逆序
    LinkList p=B->next;
    while(p) //对于B中的每个结点p
    {
        ListInsert_WithHeadNode(A,p->data);//将p->data插入到非递减有序的单链表A中的合适位置
        p=p->next;
    }
    //
    LinkListwithHeadNodeInvert(A); //参照题2.6，对带头结点的单链表实现就地逆置
    return OK;
}
