#include<iostream>
using namespace std;

int main(){
    int x,y,z;
    for(x=0;x<=20;x++)//公鸡不会超过20只
        for(y=0;y<=34;y++)//母鸡不会超过34只
            for(z=0;z<=100;z++)//小鸡不会超过100只
                if((x+y+z)==100 && (5*x+3*y+z/3)==100&&z%3==0)//同时要满足z是3的倍数
