#include <limits.h>
int pred = INT_MIN;              /* 中序前驱值，初值 -∞ */

int IsBST(BiTree T) {
    if (T == NULL) return 1;     /* 空树是 BST */
    if (!IsBST(T->lchild)) return 0;
